// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint128 amount) public {
        vm.assume(actor != address(0));
        uint256 amt = uint256(bound(amount, 1, 1 ether));

        vm.deal(actor, amt);
        vm.prank(actor);
        (bool sentDeposit, ) = address(c).call{value: amt}("");
        require(sentDeposit);

        uint256 before = c.balances(actor);
        require(before == amt);

        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        require(ok);

        assertTrue(c.balances(actor) == 0);
    }
}
